<?php
declare(strict_types=1); require_once __DIR__.'/includes/functions.php';
$message=null;$success=false;$email=$_SESSION['verification_email']??'';
$token=trim($_GET['token']??'');
if($token){$hash=verification_hash($token);$s=$pdo->prepare("SELECT id,email FROM usuarios WHERE token_verificacao=? AND token_expira_em>=NOW() LIMIT 1");$s->execute([$hash]);$u=$s->fetch();if($u){$pdo->prepare("UPDATE usuarios SET email_verificado_em=NOW(),token_verificacao=NULL,token_expira_em=NULL WHERE id=?")->execute([$u['id']]);$success=true;$message='E-mail verificado com sucesso. Agora você já pode entrar.';}else{$message='O link é inválido ou já expirou.';}}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=trim($_POST['email']??'');$s=$pdo->prepare("SELECT id,nome,email FROM usuarios WHERE email=? AND email_verificado_em IS NULL LIMIT 1");$s->execute([$email]);$u=$s->fetch();if($u){$token=verification_token();$pdo->prepare("UPDATE usuarios SET token_verificacao=?,token_expira_em=DATE_ADD(NOW(),INTERVAL 24 HOUR) WHERE id=?")->execute([verification_hash($token),$u['id']]);$sent=send_verification_email($u['nome'],$u['email'],$token);$message=$sent?'Um novo link foi enviado para seu e-mail.':'Não foi possível enviar o e-mail. Verifique a configuração de e-mail do XAMPP.';}else{$message='Não encontramos uma conta pendente de verificação para esse e-mail.';}}
?>
<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Verificar e-mail | MesaReserva</title><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@500;600;700&family=Material+Symbols+Outlined:opsz,wght,FILL,GRAD@20..48,300..600,0..1,0..200" rel="stylesheet"><link rel="stylesheet" href="<?= url('assets/css/style.css?v=20260910b') ?>"></head><body><div class="center-page"><div class="verify-card"><a href="<?= url() ?>"><img src="<?= url('assets/img/logo.png') ?>" class="login-logo" alt="MesaReserva"></a><?php if($success): ?><div class="verify-icon success"><span class="material-symbols-outlined">mark_email_read</span></div><h1>E-mail confirmado!</h1><p><?= e($message) ?></p><a class="btn btn-primary" href="<?= url('login.php') ?>">Ir para o login</a><?php else: ?><div class="verify-icon"><span class="material-symbols-outlined">mark_email_unread</span></div><h1>Confirme seu e-mail</h1><p>Enviamos um link de confirmação para o endereço informado no cadastro. O link fica disponível por 24 horas.</p><?php if($message): ?><div class="login-error"><?= e($message) ?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="form-group"><label>Seu e-mail</label><input class="form-control" type="email" name="email" value="<?= e($email) ?>" required></div><button class="btn btn-primary login-submit">Reenviar confirmação</button></form><?php if(!empty($_SESSION['verification_token_debug'])): ?><div class="local-mail-fallback"><strong>Ambiente local</strong><span>O XAMPP não enviou o e-mail automaticamente. Para testar a confirmação, use o botão abaixo.</span><a href="<?= url('verificar-email.php?token='.urlencode($_SESSION['verification_token_debug'])) ?>">Confirmar e-mail de teste</a></div><?php unset($_SESSION['verification_token_debug']); endif; ?><a class="back-link" href="<?= url('login.php') ?>">Voltar para o login</a><?php endif; ?></div></div></body></html>